export function getDivision(id: string): CompanyDivision | undefined {
  return COMPANY_DIVISIONS.find((d) => d.id === id);
}

export function divisionsByCategory(): Map<DivisionCategory, CompanyDivision[]> {
  const map = new Map<DivisionCategory, CompanyDivision[]>();
  for (const d of COMPANY_DIVISIONS) {
    const list = map.get(d.category) ?? [];
    list.push(d);
    map.set(d.category, list);
  }
  return map;
}

/** Platform Hub module shape derived from company divisions */
export type PlatformModuleFromDivision = {
  id: string;
  title: string;
  description: string;
  route: string;
  icon: string;
  gradient: string;
  status: "live" | "soon";
  locked?: boolean;
  adminOnly?: boolean;
  category: DivisionCategory;
};

export function divisionsToPlatformModules(): PlatformModuleFromDivision[] {
  return COMPANY_DIVISIONS.map((d) => ({
    id: d.id,
    title: d.title,
    description: d.description,
    route: `/company/${d.id}`,
    icon: d.icon,
    gradient: d.gradient,
    status: d.status === "planned" ? "soon" as const : "live" as const,
    locked: d.locked,
    adminOnly: d.adminOnly,
    category: d.category,
  }));
}
